Validate-Input.body:
// TEST JOB 1: Core data operations & assertions (common adaptor, no config needed)

// 1. Generate some data into state
fn(state => {
  const users = [
    { id: 1, name: 'alice', active: true },
    { id: 2, name: 'bob', active: false },
    { id: 3, name: 'carol', active: true },
  ];
  return { ...state, data: { users } };
});

// 2. Transform: map + filter active users, uppercase names
fn(state => {
  const activeNames = state.data.users
    .filter(u => u.active)
    .map(u => u.name.toUpperCase());
  return { ...state, activeNames };
});

// 3. Iterate with each() to test list handling
each(
  '$.data.users[*]',
  fn(state => {
    console.log('Processing user:', state.data.name);
    return state;
  })
);

// 4. PASS/FAIL criteria — run fails if any assertion is false
fn(state => {
  assert(
    state.data.users.length === 3,
    'FAIL: expected 3 users'
  );
  assert(
    state.activeNames.length === 2,
    'FAIL: expected 2 active users'
  );
  assert(
    state.activeNames.includes('ALICE'),
    'FAIL: ALICE missing from active names'
  );
  console.log('PASS: all assertions passed for job 1');
  return state;
});

Make-HTTP-Request.body:
// HTTP adaptor test - hits httpbin.org, no credentials required

// 1. GET request - verify we can read a response
get('https://httpbin.org/json');
fn(state => {
  const body = state.data;
  if (!body || !body.slideshow) {
    throw new Error('FAIL: GET did not return expected slideshow data');
  }
  console.log('PASS: GET request returned expected data');
  return state;
});

// 2. POST request - send data and verify it echoes back
post('https://httpbin.org/post', {
  body: { name: 'OpenFn', test: true },
});
fn(state => {
  const echoed = state.data.json;
  if (!echoed || echoed.name !== 'OpenFn' || echoed.test !== true) {
    throw new Error('FAIL: POST did not echo the sent payload correctly');
  }
  console.log('PASS: POST request echoed payload correctly');

  // Verify status code
  if (state.response.statusCode !== 200) {
    throw new Error(`FAIL: expected status 200, got ${state.response.statusCode}`);
  }
  console.log('PASS: status code is 200');

  return state;
});

