  state => state.summary.hasData === true,
  'FAIL: expected data on state from previous steps'
);

assert(
  state => state.summary.referenceCount >= 0,
  'FAIL: references should be an array'
);

fn(state => {
  console.log('PASS: all workflow test criteria met');
  return state;
});

