// Self-contained test: CSV parsing, conditional logic, merge, validation
// No credentials or input required.

// 1. Parse a CSV string into structured data
parseCsv(
  `id,name,score
1,Alice,90
2,Bob,75
3,Carol,55`,
  { columns: true, skip_empty_lines: true },
  (state, rows) => {
    state.rows = rows;
    console.log(`Parsed ${rows.length} CSV rows`);
    return state;
  }
);

// 2. Conditionally flag passing scores (>= 60)
fnIf(
  state => state.rows.length > 0,
  fn(state => {
    state.rows = state.rows.map(r => ({
      ...r,
      score: Number(r.score),
      passed: Number(r.score) >= 60,
    }));
    return state;
  })
);

// 3. Merge a static field into every row
merge(
  state => state.rows,
  fields(field('processedAt', () => new Date().toISOString()))
);

// 4. Build a summary string and validate the shape of the data
fn(state => {
  const names = arrayToString(
    state.data.map(r => r.name),
    ', '
  );
  console.log(`Students: ${names}`);

  const schema = {
    type: 'object',
    required: ['id', 'name', 'score', 'passed'],
    properties: {
      id: { type: 'string' },
      name: { type: 'string' },
      score: { type: 'number' },
      passed: { type: 'boolean' },
    },
  };

  // Validate every row against the schema
  state.data.forEach(row => {
    const result = validate(schema, row);
    assert(
      result === true || (result && result.valid !== false),
      `Row failed schema validation: ${JSON.stringify(row)}`
    );
  });

  return state;
});

// 5. Define overall pass/fail criteria
fn(state => {
  const passedCount = state.data.filter(r => r.passed).length;
  console.log(`${passedCount} of ${state.data.length} students passed`);

  assert(state.data.length === 3, 'Expected 3 rows from CSV');
  assert(passedCount === 2, 'Expected exactly 2 passing students');

  console.log('✅ CSV/validation test passed');
  return state;
});

Final-Summary-Log.body:
// FINAL SUMMARY JOB
// Uses the `common` adaptor. No credentials or input required.
// Rolls up the accumulated state from previous steps and defines
// overall pass/fail criteria via assert().

fn((state) => {
  const startedAt = new Date().toISOString();
  console.log('=== OpenFn Platform Test Summary ===');
  console.log('Summary generated at:', startedAt);

  // Collect whatever previous steps left on state.
  const checks = [];

  const add = (name, passed, detail) => {
    checks.push({ name, passed: !!passed, detail: detail || '' });
  };

  // 1. State object exists and is usable
  add('state is an object', state && typeof state === 'object');

  // 2. Data was carried through the workflow
  add('state.data present', state.data !== undefined, `typeof=${typeof state.data}`);

  // 3. References from prior steps accumulated
  const refCount = Array.isArray(state.references) ? state.references.length : 0;
  add('has references from prior steps', refCount >= 0, `references=${refCount}`);

  // 4. No error leaked onto state
  add('no error on state', !state.error, state.error ? String(state.error) : 'clean');

  // Log the results table
  console.log('--- Checks ---');
  checks.forEach((c) => {
    console.log(`${c.passed ? 'PASS' : 'FAIL'} | ${c.name}${c.detail ? ' (' + c.detail + ')' : ''}`);
  });

  const passedCount = checks.filter((c) => c.passed).length;
  const failedCount = checks.length - passedCount;
  console.log(`--- Totals: ${passedCount} passed, ${failedCount} failed ---`);

  return {
    ...state,
    summary: {
      generatedAt: startedAt,
      passed: passedCount,
      failed: failedCount,
      checks,
    },
  };
});

// PASS/FAIL CRITERIA: fail the run if any check failed.
assert(
  (state) => state.summary && state.summary.failed === 0,
  'Final summary detected one or more failed checks - see logs above'
);

