});

qa-summary.body:
// qa-summary: Final QA reporting node.
// - Does NOT make any HTTP request.
// - Reads accumulated results from state.qaResults (each: name, endpoint, passed, detail).
// - Builds a summary (total, passed, failed, failed names, timestamp) at state.qaSummary.
// - Logs a readable line per check plus the totals.

fn(state => {
  const results = state.qaResults || [];

  const passed = results.filter(r => r.passed);
  const failed = results.filter(r => !r.passed);

  const summary = {
    total: results.length,
    passed: passed.length,
    failed: failed.length,
    failedChecks: failed.map(r => r.name),
    timestamp: new Date().toISOString(),
  };

  // Log a readable line per check
  results.forEach(r => {
    console.log(`${r.passed ? 'PASS' : 'FAIL'} - ${r.name} (${r.endpoint})${r.detail ? ' :: ' + r.detail : ''}`);
  });

  // Log the totals
  console.log(`QA Summary: ${summary.passed}/${summary.total} passed, ${summary.failed} failed`);
  if (summary.failed > 0) {
    console.log(`Failed checks: ${summary.failedChecks.join(', ')}`);
  }

  return { ...state, qaSummary: summary };
});

notify-failures.body:
// notify-failures: Compile a QA failure report and email it to megan@openfn.org.
// - Reads state.qaResults (array of {name, endpoint, passed, detail}).
// - Reads state.errors (object keyed by step id: {message, details, operationName, line, ...}).
// - Always emails a full breakdown. Never throws.

fn(state => {
  const results = state.qaResults || [];
  const errors = state.errors || {};

  const passed = results.filter(r => r.passed);
  const failedResults = results.filter(r => !r.passed);
  const errorEntries = Object.entries(errors);

  const totalFailures = failedResults.length + errorEntries.length;

  const summaryLine = `QA Health Check: ${passed.length}/${results.length} checks passed, ${failedResults.length} failed` +
    (errorEntries.length ? `, ${errorEntries.length} step error(s)` : '');

  // Dog image URL captured by the dog-image check
  const dogResult = results.find(r => r.name === 'dog-image');
  const dogUrl = dogResult && dogResult.passed ? dogResult.detail : null;

  const line = '='.repeat(60);
  const sub = '-'.repeat(60);

  const parts = [];
  parts.push(line);
  parts.push('QA HEALTH CHECK REPORT');
  parts.push(new Date().toISOString());
  parts.push(summaryLine);
  if (dogUrl) {
    parts.push('');
    parts.push(`Dog of the day: ${dogUrl}`);
  }
  parts.push(line);
  parts.push('');

  // FAILED section
  parts.push(`FAILED (${totalFailures})`);
  parts.push(sub);
  if (totalFailures === 0) {
    parts.push('No failures. \u{1F389}');
  } else {
    failedResults.forEach(r => {
      parts.push(`\u2718 ${r.name}`);
      parts.push(`  Endpoint: ${r.endpoint || 'n/a'}`);
      parts.push(`  Detail:   ${r.detail || 'n/a'}`);
      parts.push('');
    });

    errorEntries.forEach(([stepId, err]) => {
      const details = err.details || {};
      const bodyText = details.body != null
        ? (typeof details.body === 'string' ? details.body : JSON.stringify(details.body, null, 2))
        : 'n/a';
      parts.push(`\u26A0 STEP ERROR: ${stepId}`);
      parts.push(`  Operation: ${err.operationName || 'n/a'}${err.line ? ' (line ' + err.line + ')' : ''}`);
      parts.push(`  Status:    ${details.statusCode != null ? details.statusCode : 'n/a'}`);
      parts.push(`  Message:   ${err.message || 'n/a'}`);
      parts.push(`  Body:      ${bodyText}`);
      parts.push('');
    });
  }

  parts.push('');

  // PASSED section
  parts.push(`PASSED (${passed.length})`);
  parts.push(sub);
  if (passed.length === 0) {
    parts.push('No successful checks.');
  } else {
    passed.forEach(r => {
      parts.push(`\u2714 ${r.name}`);
      parts.push(`  Endpoint: ${r.endpoint || 'n/a'}`);
      parts.push(`  Detail:   ${r.detail || 'n/a'}`);
      parts.push('');
    });
  }

  parts.push(line);
  parts.push('Automated QA Health Check \u00B7 OpenFn');
  parts.push(line);

  const body = parts.join('\n');

  const subject = totalFailures > 0
    ? `QA Health Check FAILED - ${totalFailures} issue(s) found`
    : `QA Health Check PASSED - all ${results.length} checks OK`;

  console.log(summaryLine);

  return { ...state, report: { subject, body, totalFailures } };
});

sendMessage({
  to: 'megan@openfn.org',
  subject: state => state.report.subject,
  body: state => state.report.body,
});

// Ensure the step never fails, even if sending errored
fn(state => {
  if (state.errors) {
    console.log('Notification step encountered errors while sending; continuing without throwing.');
  }
  return state;
});

httpbin-get.body:
// QA health-check node: httpbin-get
// - Sends a GET request to https://httpbin.org/get?qa=openfn
// - Verifies the response echoes back the request (args + url present)
// - Appends a result object to the shared state.qaResults array
// - Never throws on failure: records passed:false so later checks still run

fn(state => {
  const name = 'httpbin-get';
  const endpoint = 'https://httpbin.org/get?qa=openfn';

  // Ensure the shared results array exists without overwriting entries
  const qaResults = state.qaResults || [];

  // Run the request inside the callback so any failure (non-2xx or network
  // error) is caught here and never aborts the workflow.
  return get(endpoint)(state)
    .then(nextState => {
      let passed = false;
      let detail = '';

      const body = nextState.data || {};
      const echoedQa = body.args && body.args.qa === 'openfn';
      const echoedUrl =
        typeof body.url === 'string' && body.url.includes('httpbin.org/get');
      passed = Boolean(echoedQa && echoedUrl);
      detail = passed
        ? 'Response echoed args.qa=openfn and url as expected.'
        : `Echo check failed. args=${JSON.stringify(body.args)}, url=${body.url}`;

      return {
        ...nextState,
        qaResults: [...qaResults, { name, endpoint, passed, detail }],
      };
    })
    .catch(error => {
      const res = error.response;
      let detail;
      if (res) {
        // HTTP error: include status code, status message and body if present
        const bodyText =
          res.body !== undefined
            ? JSON.stringify(res.body)
            : res.data !== undefined
            ? JSON.stringify(res.data)
            : '(no body)';
        detail = `HTTP ${res.status} ${res.statusText || ''}. Body: ${bodyText}`;
      } else {
        // Network failure or other error with no HTTP response
        detail = `Network error: ${error.message}`;
      }

      return {
        ...state,
        qaResults: [...qaResults, { name, endpoint, passed: false, detail }],
      };
    });
});

httpbin-post.body:
// Node: httpbin-post
// Sends a POST to https://httpbin.org/post with a small JSON body.
// Verifies the response's `json` field echoes back the body we sent.
// Appends a QA result to the shared state.qaResults array (never overwrites).
// Records passed:false on failure instead of throwing.

const endpoint = 'https://httpbin.org/post';

fn(state => {
  // ensure the shared array exists without overwriting existing entries
  const qaResults = state.qaResults || [];

  const body = { qa: 'openfn', ts: Date.now() };

  // Invoke the request inside fn so we can catch any failure.
  // A non-2xx response or a network error rejects here instead of
  // aborting the whole workflow.
  return post(endpoint, body)(state)
    .then(nextState => {
      // ---- success: keep the existing check logic ----
      const echoed = nextState.data && nextState.data.json;

      const passed =
        !!echoed && echoed.qa === 'openfn' && typeof echoed.ts !== 'undefined';

      const result = {
        name: 'httpbin-post',
        endpoint,
        passed,
        detail: passed
          ? 'Response json echoed the posted body.'
          : `Echo mismatch: ${JSON.stringify(echoed)}`,
      };

      return { ...nextState, qaResults: [...qaResults, result] };
    })
    .catch(error => {
      // ---- failure: never throw, record passed:false ----
      const response = error && error.response;

      let detail;
      if (response) {
        const bodyText =
          typeof response.data === 'undefined'
            ? ''
            : ` Body: ${JSON.stringify(response.data)}`;
        detail = `HTTP ${response.status} ${response.statusText || ''}.${bodyText}`.trim();
      } else {
        detail = `Network error: ${(error && error.message) || String(error)}`;
      }

      const result = {
        name: 'httpbin-post',
        endpoint,
        passed: false,
        detail,
      };

      return { ...state, qaResults: [...qaResults, result] };
    });
});

httpbin-status.body:
// httpbin-status: QA health-check node
// Sends a GET request to https://httpbin.org/status/200
// Verifies the returned status code is 200
// Appends a result object to the shared state.qaResults array (never overwrites existing entries)
// Any HTTP failure (non-2xx or network error) is caught and recorded - it never aborts the run

fn(state => {
  const name = 'httpbin-status';
  const endpoint = 'https://httpbin.org/status/200';

  // append exactly one entry to state.qaResults without overwriting existing ones
  const append = (s, result) => ({
    ...s,
    qaResults: [...(s.qaResults || []), result],
  });

  try {
    // parseAs 'text' so we can read the raw body even on failures
    return get(endpoint, { parseAs: 'text' })(state)
      .then(nextState => {
        const status = nextState.response?.statusCode;
        const passed = status === 200;
        return append(nextState, {
          name,
          endpoint,
          passed,
          detail: passed
            ? 'Returned expected status 200'
            : `Expected status 200 but got ${status}`,
        });
      })
      .catch(error => {
        const response = error.response;
        let detail;
        if (response) {
          // non-2xx HTTP response: include status code, status message and body
          detail = `HTTP ${response.status} ${response.statusText || ''}`.trim();
          if (response.data !== undefined && response.data !== null && response.data !== '') {
            const body =
              typeof response.data === 'string'
                ? response.data
                : JSON.stringify(response.data);
            detail += ` - body: ${body}`;
          }
        } else {
          // network / connection failure: no response, use the error message
          detail = `Network error: ${error.message}`;
        }
        return append(state, { name, endpoint, passed: false, detail });
      });
  } catch (error) {
    // safety net: never throw
    return append(state, {
      name,
      endpoint,
      passed: false,
      detail: `Network error: ${error.message}`,
    });
  }
});

httpbin-headers.body:
// httpbin-headers QA health check
// Sends a GET request to https://httpbin.org/headers
// Verifies the response contains a headers object that includes a Host header
// Appends a result to the shared state.qaResults array (never overwrites existing entries)
// Does not throw on failure - records passed:false with detail instead

fn(state => {
  const endpoint = 'https://httpbin.org/headers';
  const name = 'httpbin-headers';

  const append = result => ({
    ...state,
    qaResults: [...(state.qaResults || []), { name, endpoint, ...result }],
  });

  return get(endpoint)(state)
    .then(nextState => {
      let passed = false;
      let detail = '';

      const headers = nextState.data && nextState.data.headers;
      if (headers && typeof headers === 'object' && headers.Host) {
        passed = true;
        detail = `Host header present: ${headers.Host}`;
      } else if (headers && typeof headers === 'object') {
        detail = 'headers object found but no Host header';
      } else {
        detail = 'no headers object in response';
      }

      return {
        ...nextState,
        qaResults: [
          ...(nextState.qaResults || []),
          { name, endpoint, passed, detail },
        ],
      };
    })
    .catch(error => {
      let detail;
      const response = error && error.response;

      if (response && response.status) {
        const status = response.status;
        const statusText = response.statusText || '';
        let body = response.data;
        if (body && typeof body === 'object') {
          body = JSON.stringify(body);
        }
        detail = `HTTP ${status} ${statusText}`.trim();
        if (body) detail += ` - body: ${body}`;
      } else {
        detail = `network error: ${error && error.message ? error.message : String(error)}`;
      }

      return append({ passed: false, detail });
    });
});

jsonplaceholder-list.body:
// jsonplaceholder-list
// QA health-check node: GETs https://jsonplaceholder.typicode.com/posts
// Verifies the response is a non-empty array whose first item has an id and title.
// Appends a { name, endpoint, passed, detail } record to the shared state.qaResults array.
// Never throws on failure and never overwrites existing qaResults entries.

fn(state => {
  const name = 'jsonplaceholder-list';
  const endpoint = 'https://jsonplaceholder.typicode.com/posts';
  const qaResults = Array.isArray(state.qaResults) ? state.qaResults : [];

  return get(endpoint)(state)
    .then(nextState => {
      const posts = nextState.data;
      const isArray = Array.isArray(posts);
      const count = isArray ? posts.length : 0;
      const first = isArray ? posts[0] : undefined;

      const passed = Boolean(
        isArray &&
        count > 0 &&
        first &&
        first.id !== undefined &&
        first.title !== undefined
      );

      const detail = passed
        ? `Received ${count} posts`
        : `Verification failed (isArray: ${isArray}, count: ${count})`;

      return {
        ...nextState,
        qaResults: [...qaResults, { name, endpoint, passed, detail }],
      };
    })
    .catch(error => {
      const response = error.response;
      let detail;

      if (response) {
        const status = response.statusCode ?? response.status ?? '';
        const message = response.statusMessage ?? '';
        const body = response.body ?? response.data;
        const bodyText =
          body === undefined || body === null || body === ''
            ? ''
            : ` - ${typeof body === 'string' ? body : JSON.stringify(body)}`;
        detail = `HTTP ${status} ${message}${bodyText}`.trim();
      } else {
        detail = `Network error: ${error.message}`;
      }

      return {
        ...state,
        qaResults: [...qaResults, { name, endpoint, passed: false, detail }],
      };
    });
});

jsonplaceholder-create.body:
// jsonplaceholder-create
// QA health-check node: POSTs a sample post to the JSONPlaceholder mock API.
// Verifies the response returns a created resource with an id (mock returns 101).
// Appends a pass/fail result to the shared state.qaResults array (never overwrites).
// The request is wrapped so any failure is caught and never aborts the run.

fn(state => {
  const name = 'jsonplaceholder-create';
  const endpoint = 'https://jsonplaceholder.typicode.com/posts';
  const qaResults = state.qaResults || [];

  return post(endpoint, {
    title: 'qa',
    body: 'openfn health check',
    userId: 1,
  })(state)
    .then(nextState => {
      const id = nextState.data && nextState.data.id;
      const passed = id != null;

      const result = {
        name,
        endpoint,
        passed,
        detail: passed
          ? `Created resource with id ${id}`
          : 'No id returned in response',
      };

      return { ...nextState, qaResults: [...qaResults, result] };
    })
    .catch(error => {
      const response = error.response;
      let detail;

      if (response) {
        const status = response.status;
        const statusMessage = response.statusText || '';
        let body = response.data;
        if (body && typeof body !== 'string') {
          try {
            body = JSON.stringify(body);
          } catch (e) {
            body = String(body);
          }
        }
        detail = `HTTP ${status} ${statusMessage}`.trim();
        if (body) detail += ` - ${body}`;
      } else {
        detail = `Network error: ${error.message}`;
      }

      const result = {
        name,
        endpoint,
        passed: false,
        detail,
      };

      return { ...state, qaResults: [...qaResults, result] };
    });
});

github-repo.body:
// github-repo: QA health-check node
// GETs https://api.github.com/repos/OpenFn/kit with a required User-Agent header.
// Verifies the response full_name equals 'OpenFn/kit'.
// Appends a pass/fail result to the shared state.qaResults array without throwing.

fn(state => {
  const endpoint = 'https://api.github.com/repos/OpenFn/kit';
  const qaResults = state.qaResults || [];

  return get(endpoint, { headers: { 'User-Agent': 'openfn-qa' } })(state)
    .then(nextState => {
      const body = nextState.data || {};
      const passed = body.full_name === 'OpenFn/kit';

      qaResults.push({
        name: 'github-repo',
        endpoint,
        passed,
        detail: passed
          ? `stargazers_count: ${body.stargazers_count}`
          : `Expected full_name 'OpenFn/kit', got '${body.full_name}'`,
      });

      return { ...nextState, qaResults };
    })
    .catch(error => {
      // A non-2xx response carries an HTTP response; a network error does not.
      const response = error.response || (error.body && error) || null;
      let detail;

      if (response && (response.status || response.statusCode)) {
        const status = response.status || response.statusCode;
        const message = response.statusText || response.statusMessage || '';
        const body = response.body ?? response.data;
        const bodyText =
          body == null
            ? 'no body'
            : typeof body === 'string'
            ? body
            : JSON.stringify(body);
        detail = `HTTP ${status} ${message} - ${bodyText}`.trim();
      } else {
        detail = `Network error: ${error.message || String(error)}`;
      }

      qaResults.push({
        name: 'github-repo',
        endpoint,
        passed: false,
        detail,
      });

      return { ...state, qaResults };
    });
});

random-user.body:
// random-user: QA health-check node
// - Sends a GET request to https://randomuser.me/api/
// - Verifies the response has a results array with one user having a name and email
// - Appends a result object to the shared state.qaResults array (never overwrites existing entries)
// - Records passed:false on failure instead of throwing
// - A non-2xx response or network error is caught here and never aborts the workflow

fn(state => {
  const endpoint = 'https://randomuser.me/api/';
  const name = 'random-user';

  // Run the request inside the fn so any failure can be caught here.
  return get(endpoint)(state)
    .then(s => {
      let passed = false;
      let detail = '';

      try {
        const results = s.data && s.data.results;
        if (!Array.isArray(results)) {
          detail = 'Response has no results array';
        } else if (results.length !== 1) {
          detail = `Expected 1 user, got ${results.length}`;
        } else {
          const user = results[0];
          const hasName = !!(user.name && (user.name.first || user.name.last));
          const hasEmail = !!user.email;
          if (hasName && hasEmail) {
            passed = true;
            detail = `Found user ${user.name.first} ${user.name.last} <${user.email}>`;
          } else {
            detail = `Missing ${!hasName ? 'name' : ''}${!hasName && !hasEmail ? ' and ' : ''}${!hasEmail ? 'email' : ''}`;
          }
        }
      } catch (e) {
        detail = `Assertion error: ${e.message}`;
      }

      const qaResults = s.qaResults || [];
      qaResults.push({ name, endpoint, passed, detail });
      return { ...s, qaResults };
    })
    .catch(err => {
      // Non-2xx response or network error: never throw, record the failure.
      const response = err && err.response;
      let detail;

      if (response) {
        const status = response.status ?? response.statusCode ?? '?';
        const statusText = response.statusText ?? response.statusMessage ?? '';
        const body = response.data ?? response.body;
        const bodyStr =
          body === undefined
            ? ''
            : ` - body: ${typeof body === 'string' ? body : JSON.stringify(body)}`;
        detail = `HTTP ${status} ${statusText}${bodyStr}`;
      } else {
        detail = `Network error: ${err && err.message ? err.message : String(err)}`;
      }

      const qaResults = state.qaResults || [];
