// Node: advice-slip
// Sends a GET request to https://api.adviceslip.com/advice
// Verifies the response has a `slip` object with a non-empty `advice` string.
// The API sometimes returns a JSON string, so parsing is handled gracefully.
// Appends a QA result { name, endpoint, passed, detail } to state.qaResults
// without overwriting existing entries and without throwing on failure.
// The request is wrapped so a non-2xx response or a network error never aborts the run.

fn(state => {
  const name = 'advice-slip';
  const endpoint = 'https://api.adviceslip.com/advice';
  const qaResults = state.qaResults || [];

  const append = (entry, base) => ({
    ...(base || state),
    qaResults: [...qaResults, entry],
  });

  const failFromResponse = res => {
    const status = res.statusCode;
    const statusText = res.statusText || '';
    let body = '';
    if (res.data !== undefined && res.data !== null && res.data !== '') {
      body =
        typeof res.data === 'string' ? res.data : JSON.stringify(res.data);
    }
    const detail = `HTTP ${status} ${statusText}`.trim() +
      (body ? ` - ${body}` : '');
    return { name, endpoint, passed: false, detail };
  };

  // validateStatus prevents non-2xx from throwing; .catch handles network errors.
  return get(endpoint, { validateStatus: () => true })(state)
    .then(s => {
      const res = s.response || {};
      const status = res.statusCode;

      // Non-2xx response: record failure with full explanation.
      if (typeof status !== 'number' || status < 200 || status >= 300) {
        return append(failFromResponse({ ...res, data: s.data }), s);
      }

      // Success: keep the existing check logic.
      let passed = false;
      let detail = null;

      try {
        let body = s.data;

        // Handle case where the API returns text that needs JSON parsing
        if (typeof body === 'string') {
          body = JSON.parse(body);
        }

        const advice = body && body.slip && body.slip.advice;

        if (typeof advice === 'string' && advice.trim().length > 0) {
          passed = true;
          detail = advice;
        } else {
          detail = 'Missing or empty slip.advice';
        }
      } catch (e) {
        passed = false;
        detail = `Failed to parse response: ${e.message}`;
      }

      return append({ name, endpoint, passed, detail }, s);
    })
    .catch(e => {
      // A response present here means an HTTP error; otherwise a network failure.
      if (e && e.response) {
        return append(failFromResponse(e.response));
      }
      return append({
        name,
        endpoint,
        passed: false,
        detail: `Request failed: ${e.message}`,
      });
    });
});

universities-search.body:
// QA health-check node: universities-search
// Sends a GET request to the Hipolabs universities API for Kenya.
// Verifies the response is a non-empty array where each university has a name and country.
// Appends a pass/fail result object to the shared state.qaResults array.
// Does not throw on failure - records passed:false instead.

fn(state => {
  const name = 'universities-search';
  const endpoint = 'http://universities.hipolabs.com/search?country=Kenya';
  const qaResults = state.qaResults || [];

  return get(endpoint)(state)
    .then(nextState => {
      // Success: run the existing check logic on the response.
      const data = nextState.data;
      const isArray = Array.isArray(data);
      const nonEmpty = isArray && data.length > 0;
      const allValid =
        nonEmpty && data.every(u => u && u.name && u.country);
      const passed = Boolean(nonEmpty && allValid);

      qaResults.push({
        name,
        endpoint,
        passed,
        detail: String(isArray ? data.length : 0),
      });

      return { ...nextState, qaResults };
    })
    .catch(error => {
      // Failure: never throw - record passed:false with a full explanation.
      const response = error && error.response;
      let detail;

      if (response) {
        // HTTP error (non-2xx response).
        const status = response.status;
        const statusText = response.statusText || '';
        let body = response.data;
        if (body && typeof body === 'object') {
          body = JSON.stringify(body);
        }
        detail =
          `HTTP ${status} ${statusText}`.trim() +
          (body ? ` - ${body}` : '');
      } else {
        // Network error (no response received).
        detail = `Network error: ${error && error.message ? error.message : String(error)}`;
      }

      qaResults.push({
        name,
        endpoint,
        passed: false,
        detail,
      });

      return { ...state, qaResults };
    });
});

qa-summary.body:
// qa-summary: Final QA reporting node.
// - Does NOT make any HTTP request.
// - Reads accumulated results from state.qaResults (each: name, endpoint, passed, detail).
// - Builds a summary (total, passed, failed, failed names, timestamp) at state.qaSummary.
// - Logs a readable line per check plus the totals.

fn(state => {
  console.log('CONSOLE_LOG_TEST_MARKER :: if you can read this line in the run logs, console.log output is ENABLED');

  const results = state.qaResults || [];

  const passed = results.filter(r => r.passed);
  const failed = results.filter(r => !r.passed);

  const summary = {
    total: results.length,
    passed: passed.length,
    failed: failed.length,
    failedChecks: failed.map(r => r.name),
    timestamp: new Date().toISOString(),
  };

  // Log a readable line per check
  results.forEach(r => {
    console.log(`${r.passed ? 'PASS' : 'FAIL'} - ${r.name} (${r.endpoint})${r.detail ? ' :: ' + r.detail : ''}`);
  });

  // Log the totals
  console.log(`QA Summary: ${summary.passed}/${summary.total} passed, ${summary.failed} failed`);
  if (summary.failed > 0) {
    console.log(`Failed checks: ${summary.failedChecks.join(', ')}`);
  }

  return { ...state, qaSummary: summary };
});

notify-failures.body:
// notify-failures: Compile a QA failure report and email it to megan@openfn.org.
// - Reads state.qaResults (array of {name, endpoint, passed, detail}).
// - Reads state.errors (object keyed by step id: {message, details, operationName, line, ...}).
// - Always emails a full breakdown. Never throws.

fn(state => {
  const results = state.qaResults || [];
  const errors = state.errors || {};

  const passed = results.filter(r => r.passed);
  const failedResults = results.filter(r => !r.passed);
  const errorEntries = Object.entries(errors);

  const totalFailures = failedResults.length + errorEntries.length;

  const summaryLine = `QA Health Check: ${passed.length}/${results.length} checks passed, ${failedResults.length} failed` +
    (errorEntries.length ? `, ${errorEntries.length} step error(s)` : '');

  // Dog image URL captured by the dog-image check
  const dogResult = results.find(r => r.name === 'dog-image');
  const dogUrl = dogResult && dogResult.passed ? dogResult.detail : null;

  const line = '='.repeat(60);
  const sub = '-'.repeat(60);

  const parts = [];
  parts.push(line);
  parts.push('QA HEALTH CHECK REPORT');
  parts.push(new Date().toISOString());
  parts.push(summaryLine);
  if (dogUrl) {
    parts.push('');
    parts.push(`Dog of the day: ${dogUrl}`);
  }
  parts.push(line);
  parts.push('');

  // FAILED section
  parts.push(`FAILED (${totalFailures})`);
  parts.push(sub);
  if (totalFailures === 0) {
    parts.push('No failures. \u{1F389}');
  } else {
    failedResults.forEach(r => {
      parts.push(`\u2718 ${r.name}`);
      parts.push(`  Endpoint: ${r.endpoint || 'n/a'}`);
      parts.push(`  Detail:   ${r.detail || 'n/a'}`);
      parts.push('');
    });

    errorEntries.forEach(([stepId, err]) => {
      const details = err.details || {};
      const bodyText = details.body != null
        ? (typeof details.body === 'string' ? details.body : JSON.stringify(details.body, null, 2))
        : 'n/a';
      parts.push(`\u26A0 STEP ERROR: ${stepId}`);
      parts.push(`  Operation: ${err.operationName || 'n/a'}${err.line ? ' (line ' + err.line + ')' : ''}`);
      parts.push(`  Status:    ${details.statusCode != null ? details.statusCode : 'n/a'}`);
      parts.push(`  Message:   ${err.message || 'n/a'}`);
      parts.push(`  Body:      ${bodyText}`);
      parts.push('');
    });
  }

  parts.push('');

  // PASSED section
  parts.push(`PASSED (${passed.length})`);
  parts.push(sub);
  if (passed.length === 0) {
    parts.push('No successful checks.');
  } else {
    passed.forEach(r => {
      parts.push(`\u2714 ${r.name}`);
      parts.push(`  Endpoint: ${r.endpoint || 'n/a'}`);
      parts.push(`  Detail:   ${r.detail || 'n/a'}`);
      parts.push('');
    });
  }

  parts.push('');

  // CONSOLE.LOG TEST section
  parts.push('CONSOLE.LOG TEST');
  parts.push(sub);
  parts.push("Open this run's logs and search for the marker line 'CONSOLE_LOG_TEST_MARKER'.");
  parts.push('If the marker is present, console.log output is ENABLED for this project.');
  parts.push('If it is absent, it is DISABLED.');
  parts.push('');

  parts.push(line);
  parts.push('Automated QA Health Check \u00B7 OpenFn');
  parts.push(line);

  const body = parts.join('\n');

  const subject = totalFailures > 0
    ? `QA Health Check FAILED - ${totalFailures} issue(s) found`
    : `QA Health Check PASSED - all ${results.length} checks OK`;

  console.log(summaryLine);
  console.log('CONSOLE_LOG_TEST_MARKER');

  return { ...state, report: { subject, body, totalFailures } };
});

sendMessage({
  to: 'megan@openfn.org',
  subject: state => state.report.subject,
  body: state => state.report.body,
});

// Ensure the step never fails, even if sending errored
fn(state => {
  if (state.errors) {
    console.log('Notification step encountered errors while sending; continuing without throwing.');
  }
  return state;
});

intentional-fail.body:
// QA health-check node: intentional-fail
// A deliberately-failing check that proves the failure-reporting path works.
// It performs no real request - it simply records a synthetic failure.
// Does not throw and completes successfully so the chain continues on on_job_success.

fn(state => {
  const name = 'intentional-fail';
  const endpoint = 'n/a - deliberate failure';
  const qaResults = state.qaResults || [];

  qaResults.push({
    name,
    endpoint,
    passed: false,
    detail:
      'Intentional/synthetic failure. This check always reports passed:false ' +
      'to verify that the QA failure-reporting and notification path works end to end. ' +
      'No external system was called and no error was thrown.',
  });

  return { ...state, qaResults };
});
